"const fs = require('fs');

const transcriptPath = "C:\\Users\\Minh Triet\\.gemini\\antigravity-ide\\brain\\4ffbbdf2-a09d-4e4c-91d9-5c9f4192c207\\.system_generated\\logs\\transcript.jsonl";
const lines = fs.readFileSync(transcriptPath, 'utf8').split('\n');

for (let i = 0; i < lines.length; i++) {
  if (!lines[i]) continue;
  try {
    const step = JSON.parse(lines[i]);
    const str = JSON.stringify(step);
    if (str.includes('a/frontend-app/src/pages/Pos.tsx')) {
      console.log(`Found in step ${step.step_index}`);
      fs.writeFileSync(`step_${step.step_index}.json`, str);
    }
  } catch(e) {
  }
}
